//		Where(buncolgen.ThreadColumns.ID.Eq(), id)
func ThreadScopeTenant(q *bun.SelectQuery, ti pagination.TenantInfo) *bun.SelectQuery {
	return ScopeTenant(q, ThreadColumns.OrganizationID, ThreadColumns.BusinessUnitID, ti)
}

// ThreadScopeTenantUpdate restricts an update query to a single tenant.
// Use this inside UpdateQuery.WhereGroup callbacks:
